/* ============================================================
   SECTION 4: String Cleaning
   ============================================================ */
+ '<h2 class="l-title">4. String Cleaning</h2>'

+ '<p class="l-text">Real-world text data is messy: extra whitespace, inconsistent casing, special characters, mixed formats. The <code>.str</code> accessor provides vectorized string methods that clean entire columns without loops. This is especially critical for NLP \u2014 feeding dirty text to a model produces dirty predictions.</p>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="kw">import</span> pandas <span class="kw">as</span> pd\n\ndf = pd.<span class="fn">DataFrame</span>({\n    <span class="str">"name"</span>: [<span class="str">"  Alice  "</span>, <span class="str">"BOB"</span>, <span class="str">"  carol "</span>, <span class="str">"DAVE"</span>, <span class="str">" Eve"</span>],\n    <span class="str">"email"</span>: [<span class="str">"Alice@Email.COM"</span>, <span class="str">"bob@email.com"</span>, <span class="str">"Carol@EMAIL.com"</span>,\n             <span class="str">"dave@email.com"</span>, <span class="str">"EVE@email.COM"</span>],\n    <span class="str">"phone"</span>: [<span class="str">"(555) 123-4567"</span>, <span class="str">"555.123.4567"</span>, <span class="str">"555-123-4567"</span>,\n             <span class="str">"5551234567"</span>, <span class="str">"+1 555 123 4567"</span>],\n    <span class="str">"comment"</span>: [<span class="str">"Great product!!!"</span>, <span class="str">"N/A"</span>, <span class="str">"  good   service  "</span>,\n               <span class="str">"TERRIBLE experience"</span>, <span class="str">"Will buy again :)"</span>]\n})\n\n<span class="cm"># ---- WHITESPACE ----</span>\ndf[<span class="str">"name"</span>] = df[<span class="str">"name"</span>].str.<span class="fn">strip</span>()     <span class="cm"># remove leading/trailing</span>\ndf[<span class="str">"comment"</span>] = df[<span class="str">"comment"</span>].str.<span class="fn">strip</span>()\n\n<span class="cm"># Collapse multiple internal spaces to one</span>\ndf[<span class="str">"comment"</span>] = df[<span class="str">"comment"</span>].str.<span class="fn">replace</span>(<span class="str">r"\\s+"</span>, <span class="str">" "</span>, regex=<span class="kw">True</span>)\n\n<span class="cm"># ---- CASE NORMALIZATION ----</span>\ndf[<span class="str">"name"</span>] = df[<span class="str">"name"</span>].str.<span class="fn">title</span>()      <span class="cm"># "alice" \u2192 "Alice"</span>\ndf[<span class="str">"email"</span>] = df[<span class="str">"email"</span>].str.<span class="fn">lower</span>()    <span class="cm"># emails are case-insensitive</span>\ndf[<span class="str">"comment"</span>] = df[<span class="str">"comment"</span>].str.<span class="fn">lower</span>() <span class="cm"># normalize for NLP</span>\n\n<span class="cm"># ---- REGEX REPLACE ----</span>\n<span class="cm"># Standardize phone numbers to digits only</span>\ndf[<span class="str">"phone_clean"</span>] = df[<span class="str">"phone"</span>].str.<span class="fn">replace</span>(<span class="str">r"[^\\d]"</span>, <span class="str">""</span>, regex=<span class="kw">True</span>)\n<span class="cm"># All become: "5551234567" (or "15551234567")</span>\n\n<span class="cm"># Remove repeated punctuation: "!!!" \u2192 "!"</span>\ndf[<span class="str">"comment"</span>] = df[<span class="str">"comment"</span>].str.<span class="fn">replace</span>(<span class="str">r"(.)\\1{2,}"</span>, <span class="str">r"\\1"</span>, regex=<span class="kw">True</span>)\n\n<span class="fn">print</span>(df[[<span class="str">"name"</span>, <span class="str">"email"</span>, <span class="str">"phone_clean"</span>, <span class="str">"comment"</span>]])</code></pre></div>'

+ '<div class="code-wrap"><div class="code-label"><span>PYTHON</span><button class="copy-btn" onclick="navigator.clipboard.writeText(this.closest(\'.code-wrap\').querySelector(\'code\').textContent)">COPY</button></div><pre class="code-block"><code><span class="cm"># ---- EXTRACT with regex groups ----</span>\n<span class="kw">import</span> pandas <span class="kw">as</span> pd\n\ndf = pd.<span class="fn">DataFrame</span>({\n    <span class="str">"text"</span>: [\n        <span class="str">"Score: 95/100"</span>,\n        <span class="str">"Score: 87/100"</span>,\n        <span class="str">"Score: 72/100"</span>,\n        <span class="str">"No score available"</span>\n    ]\n})\n\n<span class="cm"># Extract the numeric score</span>\ndf[<span class="str">"score"</span>] = df[<span class="str">"text"</span>].str.<span class="fn">extract</span>(<span class="str">r"(\\d+)/100"</span>)\n<span class="fn">print</span>(df[<span class="str">"score"</span>])\n<span class="cm"># 0      95</span>\n<span class="cm"># 1      87</span>\n<span class="cm"># 2      72</span>\n<span class="cm"># 3     NaN  \u2190 no match = NaN</span>\n\n<span class="cm"># Extract multiple groups</span>\naddresses = pd.<span class="fn">Series</span>([<span class="str">"New York, NY 10001"</span>, <span class="str">"Los Angeles, CA 90001"</span>])\nextracted = addresses.str.<span class="fn">extract</span>(<span class="str">r"(.+),\\s*(\\w{2})\\s*(\\d{5})"</span>)\nextracted.columns = [<span class="str">"city"</span>, <span class="str">"state"</span>, <span class="str">"zip"</span>]\n<span class="fn">print</span>(extracted)\n\n<span class="cm"># ---- CONTAINS for filtering ----</span>\n<span class="cm"># Filter reviews containing sentiment words</span>\nreviews = pd.<span class="fn">Series</span>([<span class="str">"great product"</span>, <span class="str">"terrible service"</span>, <span class="str">"okay"</span>, <span class="str">"amazing quality"</span>])\npositive = reviews[reviews.str.<span class="fn">contains</span>(<span class="str">r"great|amazing|excellent"</span>, case=<span class="kw">False</span>)]\n<span class="fn">print</span>(positive.tolist())  <span class="cm"># [\'great product\', \'amazing quality\']</span></code></pre></div>'

/* --- Plotly: Before/After Cleaning (EN) --- */
+ '<div id="plot-strclean-en" class="plotly-graph"></div>'
+ '<script>setTimeout(function(){'
