+ 'var t2={type:"scatterpolar",r:after.concat([after[0]]),theta:metrics.concat([metrics[0]]),fill:"toself",name:"After Cleaning",fillcolor:"rgba(77,232,122,0.15)",line:{color:"#4de87a",width:2},marker:{size:6}};'
